def courbe(pts, xl, yl, w=150, ymax=110, xmax=12, title=""):
    """Graphique en ligne simple (SVG) : pts = [(x, y), …]."""
    X = lambda x: 40 + x * 250 / xmax
    Y = lambda y: 170 - y * 150 / ymax
    grid = "".join(f'<line x1="40" y1="{Y(v)}" x2="290" y2="{Y(v)}" stroke="#e3e6ec"/><text x="34" y="{Y(v) + 4}" font-size="9" text-anchor="end">{v}</text>' for v in range(0, ymax + 1, 20 if ymax > 50 else 5))
    gx = "".join(f'<text x="{X(v)}" y="184" font-size="9" text-anchor="middle">{v}</text>' for v in range(0, xmax + 1, 2))
    path = " ".join(f"{'M' if i == 0 else 'L'}{X(x):.1f} {Y(y):.1f}" for i, (x, y) in enumerate(pts))
    dots_ = "".join(f'<circle cx="{X(x):.1f}" cy="{Y(y):.1f}" r="3" fill="{MC}"/>' for x, y in pts)
    return f'''<svg viewBox="0 0 300 200" width="{w}mm" style="max-width:100%;height:auto" font-family="Poppins,DejaVu Sans" fill="#1F2A44">
<text x="165" y="12" font-size="10.5" font-weight="700" text-anchor="middle">{title}</text>{grid}{gx}
<line x1="40" y1="20" x2="40" y2="170" stroke="#1F2A44" stroke-width="1.5"/><line x1="40" y1="170" x2="292" y2="170" stroke="#1F2A44" stroke-width="1.5"/>
<path d="{path}" fill="none" stroke="{MC}" stroke-width="2.5"/>{dots_}
<text x="165" y="198" font-size="9.5" text-anchor="middle">{xl}</text><text x="10" y="95" font-size="9.5" transform="rotate(-90 10 95)" text-anchor="middle">{yl}</text></svg>'''


def build_v3m3(start=1, tstart=1, render=True):
    b = Book("V3 · M3", "Volume 3 · Je réussis à l'école · Module 3 · La langue des sciences", MC, start=start)
    E = Ex(b)
    vis = ('<div class="flex" style="justify-content:space-around;align-items:flex-end">' + avatar("daria", 80, "pense") + '<div style="font-size:36pt">🔬 🌱</div>' + avatar("yonas", 80, "surpris") + '<div style="font-size:36pt">🧪 🌡️</div>'
           + avatar("fatou", 80, "sourire") + '<div style="font-size:36pt">📊 🧲</div>' + avatar("educ", 80, "sourire") + '</div>')
    opening(b, MC, 3, "La langue des sciences", vis, [("🔬", "décrire une expérience et ce que j'observe"), ("💡", "formuler une hypothèse et la vérifier"), ("🧊", "nommer les états de la matière, le vivant, le matériel de labo"),
            ("📏", "utiliser le présent de vérité générale"), ("🔗", "exprimer la cause et la conséquence"), ("📝", "lire un protocole, légender un schéma, écrire un rapport d'expérience")],
            ["As-tu déjà fait une expérience scientifique ? Laquelle ?", "Pourquoi la glace fond-elle au soleil ? Explique avec tes mots.", "Dans ton pays, le cours de sciences était-il différent ?"],
            ["une expérience", "une hypothèse", "observer", "mesurer", "un protocole", "un schéma", "la matière", "le vivant", "parce que", "donc"], TINT)

    # ---------- Découvrir ----------
    bd = '<div class="grid2" style="gap:3mm">' + "".join([
        bd_case(1, lr("educ", ["Aujourd'hui, au labo, nous faisons germer des graines de haricot. Question : est-ce qu'une graine a besoin de lumière pour germer ?"], "yonas", ["Évidemment ! Les plantes ont besoin de soleil !"], "sourire", "rire")),
        bd_case(2, lr("educ", ["Attention, Yonas : ce que tu dis, c'est une hypothèse. En sciences, on doit la vérifier par une expérience."], "daria", ["Alors on met des graines dans le noir et d'autres à la lumière ?"], "sourire", "pense")),
        bd_case(3, lr("educ", ["Exactement ! Et on ne change qu'une seule chose : la lumière. Le reste est pareil : la même eau, le même coton, la même température."], "fatou", ["Comme ça, on saura si c'est vraiment la lumière qui compte !"], "sourire", "rire")),
        bd_case(4, lr("bilal", ["Une semaine plus tard… Regardez ! Les graines ont germé dans le noir aussi !"], "yonas", ["Quoi ? Mon hypothèse est fausse ?"], "surpris", "surpris")),
        bd_case(5, lr("educ", ["On dit qu'elle est infirmée. La graine contient des réserves : pour germer, elle a besoin d'eau, d'air et de chaleur. La lumière devient nécessaire après, pour que la plantule grandisse et verdisse."], "amina", ["C'est pour ça que les pousses du placard sont toutes jaunes !"], "sourire", "rire")),
        bd_case(6, lr("educ", ["Bravo ! Maintenant, vous écrivez le rapport : la question, l'hypothèse, le protocole, les observations et la conclusion."], "yonas", ["D'accord… mais la prochaine fois, je ne dirai plus « évidemment » !"], "sourire", "rire")),
    ]) + '</div>'
    e = E("J'écoute et je lis la BD : la graine a-t-elle besoin de lumière ?", bd, ["ecoute", "lis"], 1, "A",
          script="Lire deux fois. Demander : « Quelle est la question de l'expérience ? Que pense Yonas ? Pourquoi M. Diallo dit-il que c'est une hypothèse ? Qu'est-ce qui change entre les deux groupes de graines ? Quel est le résultat ? De quoi la graine a-t-elle besoin pour germer ? »", sol="Activité orale.")
    b.page(f'<h2>Découvrir · Au labo</h2>{e}', "Découvrir")
    e = E("Je réponds par une phrase complète.", f'<p>1. Quelle est la question de l\'expérience ? {blank("xl")}</p><p>2. Quelle est l\'hypothèse de Yonas ? {blank("xl")}</p><p>3. Quelle est la seule chose qui change entre les deux groupes de graines ? Pourquoi ? {blank("xl")}</p><p>4. Quel est le résultat de l\'expérience ? {blank("xl")}</p><p>5. De quoi une graine a-t-elle besoin pour germer ? {blank("xl")}</p>', ["lis", "ecris"], 1, "B",
          sol="1. Est-ce qu'une graine a besoin de lumière pour germer ? — 2. Les graines ont besoin de lumière pour germer. — 3. La lumière : on ne change qu'une chose pour savoir si c'est vraiment elle qui compte. — 4. Les graines ont germé dans le noir aussi : l'hypothèse est fausse (infirmée). — 5. D'eau, d'air et de chaleur (elle utilise ses réserves).")
    e2 = E("Vrai ou faux ? Je coche et je corrige les phrases fausses.", vf(["Yonas a raison : les graines ne germent pas dans le noir.", "Dans l'expérience, on change une seule chose.", "Une hypothèse est une idée qu'on doit vérifier.", "Les pousses qui grandissent dans le noir sont jaunes."]), ["lis", "coche"], 1, "B",
           sol="Faux (elles germent aussi dans le noir) · Vrai · Vrai · Vrai")
    e3 = E("Les mots de la BD. Je trouve le mot qui veut dire…", '<p>1. le laboratoire, en abrégé : le ______ 2. commencer à pousser (pour une graine) : ______________ 3. une idée à vérifier : une ______________ 4. montrer qu\'une hypothèse est fausse : l\'______________ 5. une très jeune plante : une ______________</p>', ["lis", "ecris"], 1, "B",
           sol="1. labo — 2. germer — 3. hypothèse — 4. infirmer — 5. plantule")
    e4 = E("Et toi ? Pour toi, de quoi une plante a-t-elle besoin pour grandir ? Écris ton hypothèse en une phrase, puis dis comment tu pourrais la vérifier.", lines(3), ["ecris"], 2, "C",
           sol="Ex. : Je pense qu'une plante a besoin d'eau pour grandir. Pour le vérifier, j'arrose une plante et pas l'autre, tout le reste étant identique, et j'observe pendant deux semaines.")
    b.page(f'{e}{e2}{e3}{e4}', "Découvrir")
    art = f'''<div class="card" style="{SERIF};background:#F7FBF9;font-size:10.3pt"><p style="margin-bottom:1mm"><b>Georges Lemaître, le prêtre belge qui a imaginé le Big Bang</b> <span class="xs muted">(texte documentaire écrit pour la classe)</span></p>
<p>Georges Lemaître est né à Charleroi en 1894. Après la Première Guerre mondiale, il étudie les mathématiques et la physique, et il devient prêtre. Il enseigne ensuite à l'Université catholique de Louvain.</p>
<p>En 1927, il publie un article étonnant : selon ses calculs, l'Univers n'est pas immobile, il est <b>en expansion</b>, c'est-à-dire qu'il grandit. Les galaxies s'éloignent les unes des autres. À cette époque, beaucoup de savants, même le célèbre Albert Einstein, pensent que l'Univers ne change pas. Lemaître va plus loin : si l'Univers grandit aujourd'hui, c'est qu'il était plus petit dans le passé. En 1931, il émet l'hypothèse d'un « atome primitif » : au début, toute la matière de l'Univers était concentrée en un point minuscule.</p>
<p>Cette idée est d'abord critiquée. En 1949, à la radio, l'astronome britannique Fred Hoyle, qui ne croit pas à cette théorie, l'appelle en se moquant le « Big Bang » (le « grand boum »). Le nom est resté ! Aujourd'hui, grâce à de nombreuses observations, la théorie du Big Bang est acceptée par la grande majorité des scientifiques.</p>
<p>L'histoire de Lemaître montre comment fonctionne la science : un chercheur propose une hypothèse, d'autres la discutent, et ce sont les observations qui permettent de la confirmer ou de l'infirmer.</p></div>'''
    e = E("Je lis le texte documentaire. Je réponds.", art + f'<p class="mt2">1. Qui était Georges Lemaître ? (3 informations) {blank("xl")}</p><p>2. Qu\'est-ce que Lemaître a découvert en 1927 ? Explique « en expansion ». {blank("xl")}</p><p>3. Pourquoi son idée était-elle étonnante à l\'époque ? {blank("xl")}</p><p>4. D\'où vient le nom « Big Bang » ? {blank("xl")}</p><p>5. Que montre cette histoire sur la science ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Un savant belge né à Charleroi en 1894, prêtre, professeur à l'Université catholique de Louvain (mathématicien, physicien). — 2. Que l'Univers est en expansion : il grandit, les galaxies s'éloignent les unes des autres. — 3. Parce que beaucoup de savants, même Einstein, pensaient que l'Univers ne changeait pas. — 4. De l'astronome Fred Hoyle, qui s'en moquait à la radio en 1949. — 5. Une hypothèse est discutée, puis confirmée ou infirmée par les observations.")
    e2 = E("Les mots du texte. Je relie le mot et sa définition.", relie(["en expansion", "émettre une hypothèse", "une galaxie", "critiquer", "la majorité"], ["un immense ensemble d'étoiles", "le plus grand nombre", "proposer une idée à vérifier", "qui devient de plus en plus grand", "dire ce qui ne va pas"]), ["lis", "relie"], 1, "B",
           sol="en expansion → de plus en plus grand · émettre une hypothèse → proposer une idée · galaxie → ensemble d'étoiles · critiquer → dire ce qui ne va pas · la majorité → le plus grand nombre")
    b.page(f'<h2>Découvrir · Un savant belge</h2>{e}{e2}', "Découvrir")

    # ---------- Lexique ----------
    etats = '''<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:2mm;text-align:center">
<div class="card" style="background:#E8F1FB"><span style="font-size:22pt">🧊</span><br><b>l'état solide</b><p class="xs" style="margin:0">forme propre, volume propre<br>(la glace, le fer, le bois)</p></div>
<div class="card" style="background:#E6F5EC"><span style="font-size:22pt">💧</span><br><b>l'état liquide</b><p class="xs" style="margin:0">prend la forme du récipient ; surface plane et horizontale<br>(l'eau, l'huile, le lait)</p></div>
<div class="card" style="background:#FFF7E0"><span style="font-size:22pt">♨️</span><br><b>l'état gazeux</b><p class="xs" style="margin:0">occupe tout l'espace disponible<br>(la vapeur d'eau, l'air)</p></div></div>
<div class="grid2 mt2" style="font-size:9.8pt"><div class="card" style="background:#fff">solide → liquide : la <b>fusion</b> (la glace <b>fond</b>)<br>liquide → solide : la <b>solidification</b> (l'eau <b>gèle</b>)</div><div class="card" style="background:#fff">liquide → gaz : la <b>vaporisation</b> (l'eau <b>bout</b>, elle <b>s'évapore</b>)<br>gaz → liquide : la <b>liquéfaction</b> ou <b>condensation</b> (la buée)</div></div>'''
    e = E("Les états de la matière. J'écoute et je répète.", etats, ["ecoute", "repete"], 1, "A",
          script="Lire chaque état et chaque changement d'état. Faire des liens avec la vie : la glace qui fond dans un verre, la flaque qui s'évapore, la buée sur la vitre de la salle de bain (condensation), l'eau qui gèle au congélateur. Rappeler : à la pression normale, l'eau pure gèle à 0 °C et bout à 100 °C.", sol="Activité orale.")
    e2 = E("Quel changement d'état ? J'écris le nom.", '<p>1. Le beurre fond dans la poêle : la ______________ 2. La flaque disparaît au soleil : l\'______________ (la vaporisation) 3. De la buée se forme sur le miroir : la ______________ 4. L\'eau devient glace au congélateur : la ______________</p>', ["lis", "ecris"], 1, "C",
           sol="1. fusion — 2. évaporation — 3. condensation (liquéfaction) — 4. solidification")
    e3 = E("Solide, liquide ou gaz ? Je classe : le sable · le jus d'orange · l'oxygène · le sucre · l'huile · la vapeur · le verre · le sang.", table(["🧊 solide", "💧 liquide", "♨️ gaz"], [["", "", ""]], ["61mm", "61mm", "60mm"]).replace("<td></td>", '<td style="height:14mm"></td>'), ["lis", "ecris"], 1, "C",
           sol="Solide : le sable, le sucre, le verre — Liquide : le jus d'orange, l'huile, le sang — Gaz : l'oxygène, la vapeur")
    e4 = E("J'écoute 5 situations de la vie. J'écris le changement d'état.", '<div class="grid5" style="gap:2mm">' + "".join(f'<div class="card c"><b>{i}</b><br>__________</div>' for i in range(1, 6)) + '</div>', ["ecoute", "ecris"], 2, "A",
           script="1. « Le linge sèche sur le fil. » — 2. « Les lunettes de Bilal se couvrent de buée quand il entre en classe. » — 3. « La neige fond sur le trottoir. » — 4. « On met du jus de fruit au congélateur pour faire des glaces. » — 5. « L'eau des pâtes bout dans la casserole. »",
           sol="1. évaporation (vaporisation) — 2. condensation (liquéfaction) — 3. fusion — 4. solidification — 5. ébullition (vaporisation)")
    b.page(f'<h2>La matière</h2>{e}{e2}{e3}{e4}', "Lexique")
    e = E("Le vivant. Je lis le schéma d'une plante à fleurs.", '<div class="grid2" style="align-items:center"><div>' + plante(True, 90) + '</div><div class="card sm" style="background:#fff">Les <b>êtres vivants</b> naissent, se nourrissent, respirent, grandissent, se reproduisent et meurent.<br><br>On les classe en groupes : les <b>végétaux</b> (les plantes), les <b>animaux</b> (les mammifères, les oiseaux, les poissons, les reptiles, les amphibiens, les insectes…), les <b>champignons</b> et les <b>micro-organismes</b> (les bactéries…).<br><br>Les plantes vertes fabriquent leur nourriture grâce à la lumière : c\'est la <b>photosynthèse</b>.</div></div>', ["lis"], 1, "B",
          sol="Lecture guidée du schéma et du texte.")
    e2 = E("Vivant ou non vivant ? Je coche.", table(["", "vivant", "non vivant"], [[x, '<span class="chk"></span>', '<span class="chk"></span>'] for x in ["un champignon", "un caillou", "une bactérie", "le feu", "un arbre", "l'eau"]], ["120mm", "30mm", "30mm"]), ["coche"], 1, "B",
           sol="vivant · non vivant · vivant · non vivant · vivant · non vivant")
    e3 = E("À quel groupe appartient l'animal ? Je relie.", relie(["la baleine", "la grenouille", "l'abeille", "le crocodile", "le requin"], ["un poisson", "un mammifère", "un reptile", "un insecte", "un amphibien"]), ["relie"], 1, "B",
           sol="baleine → mammifère · grenouille → amphibien · abeille → insecte · crocodile → reptile · requin → poisson")
    b.page(f'<h2>Le vivant</h2>{e}{e2}{e3}', "Lexique")
    lab = [("🧪", "une éprouvette"), ("🥛", "un bécher"), ("🌡️", "un thermomètre"), ("⚖️", "une balance"), ("🔬", "un microscope"), ("🔍", "une loupe"), ("🔥", "un bec Bunsen"), ("🧤", "des gants"), ("🥽", "des lunettes de protection"), ("🥼", "une blouse"), ("💧", "une pipette"), ("⏱️", "un chronomètre")]
    e = E("Le matériel du laboratoire. J'écoute et je répète.", emogrid(lab, 6, False).replace('font-size:10pt', 'font-size:9pt'), ["ecoute", "repete"], 1, "A",
          script="Nommer chaque objet avec son article et dire à quoi il sert (contenir, mesurer, grossir, chauffer, prélever, protéger).", sol="Activité orale.")
    e2 = E("À quoi sert-il ? Je complète avec : mesurer · grossir · chauffer · protéger · prélever.", '<div class="card" style="line-height:2">1. La balance sert à ______________ une masse. 2. Le microscope sert à ______________ ce qui est très petit. 3. Le bec Bunsen sert à ______________ . 4. Les lunettes servent à ______________ les yeux. 5. La pipette sert à ______________ quelques gouttes.</div>', ["complete"], 1, "C",
           sol="1. mesurer — 2. grossir (observer) — 3. chauffer — 4. protéger — 5. prélever")
    e3 = E("Les règles de sécurité au labo. Je relie le début et la fin de la règle.", relie(["Je porte des lunettes", "Je ne goûte jamais", "J'attache", "Je lis le protocole", "Je préviens le professeur"], ["mes cheveux longs.", "avant de commencer.", "pour protéger mes yeux.", "en cas d'accident.", "les produits."]), ["relie"], 1, "B",
           sol="lunettes → protéger mes yeux · ne goûte jamais → les produits · j'attache → mes cheveux longs · protocole → avant de commencer · préviens → en cas d'accident")
    b.page(f'<h2>Le laboratoire</h2>{e}{e2}{e3}', "Lexique")
    verbs = table(["Le verbe", "Le nom", "Exemple"], [["observer", "l'observation", "J'observe les graines à la loupe."], ["mesurer", "la mesure", "Je mesure la température de l'eau."], ["chauffer", "le chauffage", "On chauffe l'eau pendant 5 minutes."], ["mélanger", "le mélange", "Je mélange le sel et l'eau."], ["dissoudre", "la dissolution", "Le sucre se dissout dans l'eau chaude."], ["filtrer", "la filtration", "On filtre l'eau boueuse."], ["peser", "la pesée", "Je pèse 20 g de sel."], ["comparer", "la comparaison", "Je compare les deux plantes."]], ["38mm", "42mm", "102mm"])
    e = E("Les verbes et les noms de la science. Je lis le tableau.", verbs, ["lis"], 1, "B", sol="Lecture guidée.")
    e2 = E("Je transforme : verbe → nom (on écrit les titres des étapes avec des noms).", '<p>1. Chauffer l\'eau → le ______________ de l\'eau 2. Observer les résultats → l\'______________ des résultats 3. Mélanger les produits → le ______________ des produits 4. Filtrer le liquide → la ______________ du liquide 5. Peser le sel → la ______________ du sel</p>', ["ecris"], 2, "C",
           sol="1. chauffage — 2. observation — 3. mélange — 4. filtration — 5. pesée")
    e3 = E("Mélange homogène ou hétérogène ? Je lis l'encadré et je coche.", '<div class="card sm" style="background:#fff">Dans un mélange <b>homogène</b>, on ne voit qu\'une seule partie (eau + sel dissous). Dans un mélange <b>hétérogène</b>, on voit plusieurs parties (eau + sable, eau + huile).</div>' + table(["", "homogène", "hétérogène"], [[x, '<span class="chk"></span>', '<span class="chk"></span>'] for x in ["eau + sucre dissous", "eau + huile", "eau + sable", "le thé (sans feuilles)"]], ["120mm", "30mm", "30mm"]), ["lis", "coche"], 2, "B",
           sol="homogène · hétérogène · hétérogène · homogène")
    b.page(f'<h2>Les verbes de la science</h2>{e}{e2}{e3}', "Lexique")

    # ---------- Leçon 1 : le présent de vérité générale ----------
    l1 = lecon("Le présent de vérité générale", '''<div class="grid2"><div class="card" style="background:#fff"><b>📏 Ce qui est vrai toujours, partout</b><p class="sm" style="margin:1mm 0 0">En sciences, on utilise le <b>présent</b> pour dire une loi, une définition, une propriété : c'est vrai hier, aujourd'hui et demain.<br><i>L'eau <b>bout</b> à 100 °C. La Terre <b>tourne</b> autour du Soleil. Les mammifères <b>allaitent</b> leurs petits. Un aimant <b>attire</b> le fer.</i></p></div>
<div class="card" style="background:#fff"><b>⏺️ ≠ le présent d'actualité</b><p class="sm" style="margin:1mm 0 0">Ce qui se passe <b>maintenant</b>, une seule fois :<br><i>En ce moment, l'eau <b>bout</b> dans la casserole. Aujourd'hui, Yonas <b>observe</b> des graines.</i><br>➜ Dans un rapport, les <b>observations</b> sont souvent au passé composé ou au présent, la <b>conclusion</b> (la loi) au présent de vérité générale.</p></div></div>''' +
                '<div class="astuce" style="margin:2mm 0 0">✏️ Les verbes difficiles des sciences au présent : <b>dissoudre</b> → il dissout, ils dissolvent · <b>se dissoudre</b> → le sel se dissout · <b>bouillir</b> → l\'eau bout, les liquides bouillent · <b>geler</b> → il gèle · <b>contenir</b> → il contient, ils contiennent · <b>absorber</b> → les racines absorbent l\'eau.</div>')
    e = E("Vérité générale 📏 ou actualité ⏺️ ? Je coche.", table(["", "📏", "⏺️"], [[x, '<span class="chk"></span>', '<span class="chk"></span>'] for x in ["Le fer rouille à l'humidité.", "Aujourd'hui, nous chauffons de l'eau au labo.", "Les plantes vertes produisent de l'oxygène.", "En ce moment, Fatou mesure la température.", "Le son ne se propage pas dans le vide."]], ["130mm", "25mm", "25mm"]), ["lis", "coche"], 1, "B",
          sol="📏 · ⏺️ · 📏 · ⏺️ · 📏")
    e0 = e
    e = E("Je conjugue au présent de vérité générale.", '<div class="card" style="line-height:2">1. Le sel (se dissoudre) ______________ dans l\'eau. 2. Les liquides (bouillir) ______________ à des températures différentes. 3. Les racines (absorber) ______________ l\'eau du sol. 4. L\'air (contenir) ______________ environ 21 % d\'oxygène. 5. Les oiseaux (pondre) ______________ des œufs. 6. La Lune (tourner) ______________ autour de la Terre.</div>', ["complete"], 1, "C",
          sol="1. se dissout — 2. bouillent — 3. absorbent — 4. contient — 5. pondent — 6. tourne")
    b.page(f'{l1}{e0}{e}', "Leçon 1")
    e2 = E("Observation (passé) → loi (présent). Je transforme comme dans l'exemple.", '<div class="card sm" style="background:#fff">Ex. : Les graines <b>ont germé</b> dans le noir. → Les graines <b>germent</b> sans lumière.</div><p>1. Le morceau de fer <b>a été attiré</b> par l\'aimant. → ______________________________</p><p>2. L\'eau <b>a gelé</b> à 0 °C. → ______________________________</p><p>3. Le sucre <b>a disparu</b> dans l\'eau chaude. → ______________________________</p>', ["ecris"], 2, "C",
           sol="1. Un aimant attire le fer. — 2. L'eau gèle à 0 °C. — 3. Le sucre se dissout dans l'eau (chaude).")
    e3 = E("Je corrige les erreurs scientifiques ET de conjugaison (une par phrase).", '<div class="card" style="font-family:monospace;background:#fff;line-height:1.9">1. L\'eau bouillit à 100 °C.<br>2. Le Soleil tourne autour de la Terre.<br>3. Les araignées sont des insectes.<br>4. Le sucre se dissoud dans l\'eau.</div>' + lines(2), ["lis", "ecris"], 2, "C",
           sol="1. L'eau bout à 100 °C. — 2. La Terre tourne autour du Soleil. — 3. Les araignées sont des arachnides (8 pattes), pas des insectes (6 pattes). — 4. Le sucre se dissout dans l'eau.")
    e4 = E("Défi ! J'écris 4 « vérités générales » que je connais (une sur la matière, une sur le vivant, une sur la Terre, une sur le corps humain).", lines(3), ["ecris"], 3, "C",
           sol="Ex. : Le fer rouille à l'humidité. Les poissons respirent avec des branchies. La Terre fait le tour du Soleil en un an. Le cœur envoie le sang dans tout le corps.")
    e5 = E("Les définitions scientifiques sont au présent. Je complète avec un verbe au présent.", '<p>1. Un mammifère est un animal qui ______________ ses petits avec son lait. 2. Un thermomètre est un instrument qui ______________ la température. 3. Les herbivores ______________ seulement des végétaux. 4. Un aimant est un objet qui ______________ le fer.</p>', ["ecris"], 1, "C",
           sol="1. nourrit (allaite) — 2. mesure — 3. mangent — 4. attire")
    b.page(f'{e2}{e3}{e4}{e5}', "S'entraîner")

    # ---------- Leçon 2 : la cause et la conséquence ----------
    l2 = lecon("Exprimer la cause et la conséquence", table(["", "Pour la CAUSE (pourquoi ?)", "Pour la CONSÉQUENCE (quel résultat ?)"], [
        ["conjonctions", "parce que · car · puisque · comme (en début de phrase)", "donc · alors · c'est pourquoi · si bien que"], ["prépositions + nom", "à cause de (négatif) · grâce à (positif) · en raison de · sous l'effet de", "d'où · par conséquent"],
        ["verbes", "être dû à · venir de · s'expliquer par", "provoquer · entraîner · causer · produire · permettre"]], ["32mm", "75mm", "75mm"]) +
                '''<div class="card mt2" style="background:#fff"><p class="sm" style="margin:0"><b>Exemples :</b> La glace fond <b>parce que</b> la température augmente. · <b>Comme</b> il fait froid, l'eau gèle. · La chaleur <b>provoque</b> la dilatation des métaux. · Les plantes poussent <b>grâce à</b> la lumière. · La flaque s'évapore <b>sous l'effet de</b> la chaleur. · Il n'a pas plu, <b>c'est pourquoi</b> les plantes ont séché.</p></div>
<div class="astuce" style="margin:2mm 0 0">⚠️ <b>à cause de</b> + une cause négative (<i>à cause de la pollution</i>) · <b>grâce à</b> + une cause positive (<i>grâce au vaccin</i>). En sciences, <b>en raison de</b> et <b>sous l'effet de</b> sont plus neutres.</div>''')
    e = E("Cause ou conséquence ? Je souligne la cause en bleu et la conséquence en rouge.", '<div class="card" style="line-height:1.9">1. Le fer rouille parce qu\'il est au contact de l\'eau et de l\'air.<br>2. La lumière manque, donc la plante jaunit.<br>3. Comme il fait très chaud, l\'eau de la mare s\'évapore.<br>4. La pollution de l\'air provoque des maladies respiratoires.</div>', ["souligne"], 1, "B",
          sol="Cause (bleu) : il est au contact de l'eau et de l'air · la lumière manque · il fait très chaud · la pollution de l'air — Conséquence (rouge) : le fer rouille · la plante jaunit · l'eau s'évapore · des maladies respiratoires")
    e0 = e
    e = E("Je complète avec : parce que · donc · grâce à · à cause de · comme.", '<div class="card" style="line-height:2">1. ______________ la température descend sous 0 °C, l\'eau gèle. 2. Les abeilles sont importantes ______________ elles transportent le pollen. 3. Beaucoup de poissons meurent ______________ la pollution. 4. La plante pousse vite ______________ la lumière et à l\'eau. 5. Le métal est chauffé, ______________ il se dilate.</div>', ["complete"], 1, "C",
          sol="1. Comme — 2. parce que (car) — 3. à cause de — 4. grâce à — 5. donc")
    b.page(f'{l2}{e0}{e}', "Leçon 2")
    e2 = E("Je relie la cause et la conséquence, puis j'écris une phrase avec un verbe (provoquer, entraîner, causer).", relie(["La chaleur", "Le manque d'eau", "Le froid intense", "L'électricité"], ["la mort des plantes", "la dilatation des métaux", "l'éclairage de l'ampoule", "le gel des lacs"]) + lines(2), ["relie", "ecris"], 2, "C",
           sol="chaleur → dilatation · manque d'eau → mort des plantes · froid → gel des lacs · électricité → éclairage. Ex. : La chaleur provoque la dilatation des métaux. Le manque d'eau entraîne la mort des plantes.")
    e3 = E("J'écoute l'explication de M. Diallo. Je complète le schéma cause → conséquence.", '<div class="flex" style="justify-content:space-between;gap:2mm;font-size:10pt">' + "".join(f'<div class="card c" style="flex:1;background:{TINT};min-height:18mm">{t}<br>______________</div>' + ('<b>➜</b>' if i < 3 else '') for i, t in enumerate(["☀️ Le soleil", "💧 L'eau des mers", "☁️ La vapeur monte, refroidit", "🌧️ Les gouttes"])) + '</div>', ["ecoute", "complete"], 2, "A",
           script="« Le soleil chauffe l'eau des mers et des lacs. À cause de cette chaleur, l'eau s'évapore : elle devient de la vapeur. La vapeur monte dans l'air ; en altitude, il fait plus froid, donc la vapeur se condense et forme des nuages de petites gouttes. Quand les gouttes deviennent trop lourdes, elles tombent : c'est la pluie. »",
           sol="chauffe l'eau · s'évapore (devient vapeur) · se condense, forme des nuages · tombent : la pluie")
    e4 = E("Défi ! J'explique en 4 phrases pourquoi la glace fond dans un verre posé au soleil. J'utilise au moins 3 expressions de la cause ou de la conséquence.", lines(4), ["ecris"], 3, "C",
           sol="Ex. : La glace fond parce que le soleil chauffe le verre et l'air autour. Sous l'effet de la chaleur, la température de la glace dépasse 0 °C. C'est pourquoi elle passe de l'état solide à l'état liquide : c'est la fusion. Donc, après quelques minutes, il ne reste que de l'eau.")
    e5 = E("Je transforme avec un nom : « parce que » → « grâce à » ou « à cause de ».", '<div class="card sm" style="background:#fff">Ex. : Les plantes poussent parce qu\'il y a de la lumière. → Les plantes poussent <b>grâce à la lumière</b>.</div><p>1. Les arbres tombent parce qu\'il y a une tempête. → ______________________________</p><p>2. On guérit plus vite parce qu\'il y a des médicaments. → ______________________________</p><p>3. Les poissons meurent parce que l\'eau est polluée. → ______________________________</p>', ["ecris"], 2, "C",
           sol="1. Les arbres tombent à cause de la tempête. — 2. On guérit plus vite grâce aux médicaments. — 3. Les poissons meurent à cause de la pollution de l'eau.")
    b.page(f'{e2}{e3}{e4}{e5}', "S'entraîner")

    # ---------- Leçon 3 : formuler une hypothèse ----------
    dem = [("❓", "1. La question", "Est-ce que… ? Pourquoi… ?"), ("💡", "2. L'hypothèse", "Je pense que… / Je suppose que…"), ("🧪", "3. L'expérience", "On teste en changeant UNE seule chose."), ("👀", "4. Les observations", "On regarde, on mesure, on note."), ("✅", "5. La conclusion", "L'hypothèse est confirmée ou infirmée.")]
    l3 = lecon("Formuler une hypothèse et la vérifier", '<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:1.5mm">' + "".join(f'<div class="card c" style="padding:1.5mm;background:#fff"><span style="font-size:16pt">{e}</span><br><b class="xs">{t}</b><p class="xs" style="margin:.5mm 0 0">{d}</p></div>' for e, t, d in dem) + '</div>' +
                table(["Pour…", "J'écris…"], [["formuler une hypothèse", "Je pense que… · Je suppose que… · Mon hypothèse est que… · Peut-être que… · J'émets l'hypothèse que… (+ indicatif)"], ["lier hypothèse et test", "<b>Si</b> mon hypothèse est juste, <b>alors</b> les graines dans le noir <b>ne germeront pas</b>."], ["conclure", "L'hypothèse est <b>confirmée</b> (= juste) · L'hypothèse est <b>infirmée</b> (= fausse) · Les résultats <b>montrent que</b>… · On <b>constate que</b>…"]], ["44mm", "138mm"]).replace('<table', '<table style="margin-top:2mm"') +
                '<div class="astuce" style="margin:2mm 0 0">🔬 <b>Une expérience juste</b> : on ne change qu\'<b>un seul facteur</b> (la variable) ; tout le reste est identique. On garde un <b>témoin</b> (le groupe où on ne change rien) pour comparer.</div>')
    e = E("Question, hypothèse ou conclusion ? J'écris Q, H ou C.", '<div class="card" style="line-height:1.9">___ Je pense que le sucre se dissout plus vite dans l\'eau chaude.<br>___ Est-ce que le sucre se dissout plus vite dans l\'eau chaude ?<br>___ Les résultats montrent que le sucre se dissout plus vite dans l\'eau chaude.<br>___ Je suppose que les plantes arrosées à l\'eau salée vont mourir.</div>', ["lis", "ecris"], 1, "B",
          sol="H · Q · C · H")
    e0 = e
    e = E("J'écris une hypothèse pour chaque question (avec 2 expressions différentes).", '<p>1. Est-ce qu\'un glaçon fond plus vite dans l\'eau ou dans l\'air ? → ______________________________</p><p>2. Est-ce que tous les métaux sont attirés par un aimant ? → ______________________________</p><p>3. Pourquoi le pain moisit-il plus vite dans un sac fermé ? → ______________________________</p>', ["ecris"], 1, "C",
          sol="Ex. : 1. Je pense que le glaçon fond plus vite dans l'eau. 2. Je suppose que tous les métaux sont attirés par un aimant (hypothèse qui sera infirmée : l'aluminium et le cuivre ne le sont pas). 3. Mon hypothèse est que l'humidité reste dans le sac et favorise les moisissures.")
    b.page(f'{l3}{e0}{e}', "Leçon 3")
    e2 = E("Si mon hypothèse est juste, alors… Je complète.", '<p>1. Hypothèse : les plantes ont besoin d\'eau. → Si mon hypothèse est juste, alors la plante non arrosée ______________________________</p><p>2. Hypothèse : le sel fait fondre la glace plus vite. → Si mon hypothèse est juste, alors le glaçon salé ______________________________</p>', ["ecris"], 2, "C",
           sol="1. … se fanera (séchera, mourra). — 2. … fondra plus vite que le glaçon sans sel.")
    e3 = E("Une expérience juste ? Je lis et je réponds.", doc("Amina veut savoir si la lumière fait pousser les plantes plus vite. Elle met une plante A au soleil et l'arrose tous les jours. Elle met une plante B dans le placard et ne l'arrose pas.") + f'<p class="mt2">1. Quel est le problème de cette expérience ? {blank("xl")}</p><p>2. Que doit-elle changer pour que l\'expérience soit juste ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
           sol="1. Elle change deux facteurs à la fois (la lumière ET l'eau) : on ne peut pas savoir lequel explique le résultat. — 2. Arroser les deux plantes de la même façon et changer seulement la lumière.")
    e4 = E("Confirmée ou infirmée ? Je lis l'hypothèse et le résultat, puis j'écris la conclusion.", table(["Hypothèse", "Résultat", "Conclusion"], [["Les objets lourds coulent toujours.", "Un gros tronc d'arbre flotte.", ""], ["Le sucre se dissout plus vite dans l'eau chaude.", "Eau chaude : 1 min ; eau froide : 6 min.", ""]], ["62mm", "60mm", "60mm"]).replace("<td></td>", '<td style="height:12mm"></td>'), ["lis", "ecris"], 2, "C",
           sol="1. L'hypothèse est infirmée : un objet lourd peut flotter. — 2. L'hypothèse est confirmée : le sucre se dissout plus vite dans l'eau chaude.")
    e5 = E("J'écoute 3 élèves. Chacun dit une hypothèse et le résultat de son expérience. J'écris « confirmée » ou « infirmée ».", '<div class="grid3">' + "".join(f'<div class="card c"><b>{n}</b><br>______________</div>' for n in ["1. Daria", "2. Mateo", "3. Fatou"]) + '</div>', ["ecoute", "ecris"], 2, "A",
           script="1. Daria : « Je pensais que le glaçon fondrait plus vite dans l'eau que dans l'air. Résultat : dans l'eau, 4 minutes ; dans l'air, 20 minutes. » — 2. Mateo : « Je supposais que l'aimant attirerait la canette en aluminium. Résultat : rien ne s'est passé. » — 3. Fatou : « Mon hypothèse : la plante arrosée à l'eau salée allait se faner. Après une semaine, ses feuilles étaient toutes jaunes et molles. »",
           sol="1. confirmée — 2. infirmée (l'aluminium n'est pas attiré) — 3. confirmée")
    b.page(f'{e2}{e3}{e4}{e5}', "S'entraîner")

    # ---------- Leçon 4 (FLSco) : le protocole et le schéma légendé ----------
    prot = f'''<div class="doc" style="transform:none;border:1.5px solid #9aa1b1;background:#fff;padding:3mm 4mm;font-size:10pt;line-height:1.45">{S} <b style="font-size:11.5pt">Protocole · La graine a-t-elle besoin de lumière pour germer ?</b>
<div class="grid2" style="gap:3mm;margin-top:1.5mm"><div><b>Matériel</b><br>• 8 graines de haricot<br>• 2 boîtes transparentes<br>• du coton<br>• de l'eau<br>• une étiquette, un marqueur</div>
<div><b>Mode opératoire</b><br>1. <b>Placer</b> du coton humide au fond des deux boîtes.<br>2. <b>Déposer</b> 4 graines dans chaque boîte.<br>3. <b>Mettre</b> la boîte A près de la fenêtre et la boîte B dans une armoire fermée, à la même température.<br>4. <b>Arroser</b> les deux boîtes avec la même quantité d'eau, tous les deux jours.<br>5. <b>Observer</b> les graines chaque jour pendant 7 jours et <b>noter</b> les observations dans un tableau.</div></div>
<p class="xs" style="margin:1.5mm 0 0">⚠️ Sécurité : se laver les mains après avoir manipulé les graines. Ne pas les manger.</p></div>'''
    l4 = lecon("Lire un protocole · légender un schéma", '<div class="grid2"><div class="card" style="background:#fff"><b>📋 Le protocole</b><p class="sm" style="margin:1mm 0 0">C\'est la <b>recette</b> de l\'expérience : un titre (la question), la liste du <b>matériel</b>, le <b>mode opératoire</b> (les étapes numérotées dans l\'ordre), les règles de sécurité. Les verbes sont à l\'<b>infinitif</b> (placer, déposer) ou à l\'<b>impératif</b> (placez, déposez).</p></div><div class="card" style="background:#fff"><b>✏️ Le schéma légendé</b><p class="sm" style="margin:1mm 0 0">• un <b>titre</b> qui dit ce qu\'on voit<br>• des <b>traits de légende</b> tracés à la latte 🇧🇪 (règle), qui ne se croisent pas<br>• des <b>légendes</b> écrites à l\'horizontale, avec un article (le bécher)<br>• un dessin simple, au crayon, sans couleurs inutiles</p></div></div>' + prot)
    e = E("Je lis le protocole. Je réponds.", f'<p>1. Quelle est la question de l\'expérience ? {blank("xl")}</p><p>2. Quelle est la seule différence entre la boîte A et la boîte B ? {blank("xl")}</p><p>3. Pourquoi faut-il arroser les deux boîtes avec la même quantité d\'eau ? {blank("xl")}</p><p>4. Relève 3 verbes à l\'infinitif et transforme-les à l\'impératif (vous). {blank("xl")}</p>', ["lis", "ecris"], 1, "B",
          sol="1. La graine a-t-elle besoin de lumière pour germer ? — 2. La lumière (A près de la fenêtre, B dans une armoire fermée). — 3. Pour ne changer qu'un seul facteur : la lumière. — 4. Ex. : placer → placez ; déposer → déposez ; observer → observez.")
    b.page(f'<span class="tag-doc">🎒 FRANÇAIS DE L\'ÉCOLE</span>{l4}{e}', "Consignes & école")
    e = E("Je légende le schéma du montage de chauffage de l'eau avec : le bécher · le thermomètre · la plaque chauffante · le support · la pince · l'eau.", '<div class="c">' + montage(False, 150) + '</div><p>Titre du schéma : ______________________________________________</p>', ["lis", "ecris"], 1, "C",
          sol="① le thermomètre · ② le support · ③ la pince · ④ le bécher · ⑤ l'eau · ⑥ la plaque chauffante — Titre : Montage pour mesurer la température de l'eau pendant le chauffage.")
    e2 = E("Je remets les étapes du protocole dans l'ordre (1 à 5).", doc("Comment séparer le sable et le sel ?") + '<div class="card mt2" style="line-height:1.8">___ Filtrer le mélange : le sable reste dans le filtre.<br>___ Verser le mélange sable + sel dans un bécher.<br>___ Chauffer l\'eau salée : l\'eau s\'évapore, le sel reste.<br>___ Ajouter de l\'eau et mélanger : le sel se dissout.<br>___ Observer le sel au fond du récipient.</div>', ["lis", "numerote"], 2, "B",
           sol="3 · 1 · 4 · 2 · 5")
    b.page(f'{e}{e2}', "Consignes & école")
    e = E("Je légende le schéma de la plante à fleurs.", '<div class="c">' + plante(False, 120) + '</div>', ["ecris"], 1, "C", sol="① la fleur · ② la feuille · ③ la tige · ④ les racines · ⑤ le fruit")
    e2 = E("Dans les autres cours ! Je reformule les consignes de sciences en mots simples.", '<div class="card sm" style="background:#fff">1. ' + S + ' « <b>Annotez</b> le schéma. » 2. ' + S + ' « <b>Interprétez</b> les résultats. » 3. ' + S + ' « <b>Émettez</b> une hypothèse. » 4. ' + S + ' « <b>Identifiez</b> la variable. »</div>' + lines(4), ["lis", "ecris"], 2, "B",
           sol="1. Écrivez les noms des parties sur le schéma (légendez). 2. Expliquez ce que veulent dire les résultats. 3. Proposez une explication à vérifier. 4. Trouvez la seule chose qu'on change dans l'expérience.")
    e3 = E("J'écris le protocole d'une expérience simple : « Le sucre se dissout-il plus vite dans l'eau chaude ? » (matériel + 4 étapes à l'infinitif).", lines(6), ["ecris"], 3, "C",
           sol="Matériel : 2 verres, eau chaude, eau froide, 2 morceaux de sucre, un chronomètre, une cuillère. Étapes : 1. Verser la même quantité d'eau chaude dans le verre A et d'eau froide dans le verre B. 2. Déposer un morceau de sucre dans chaque verre en même temps. 3. Déclencher le chronomètre. 4. Noter le temps de dissolution de chaque morceau.")
    b.page(f'{e}{e2}{e3}', "Consignes & école")

    # ---------- Leçon 5 : le rapport d'expérience ----------
    l5 = lecon("Écrire un rapport d'expérience", table(["Partie", "Ce que j'écris", "Temps / langue"], [
        ["1. Titre et question", "Le sucre se dissout-il plus vite dans l'eau chaude ?", "phrase interrogative"], ["2. Hypothèse", "Je pense que…", "présent ou futur"], ["3. Matériel et protocole", "liste + étapes numérotées", "infinitif"],
        ["4. Observations / résultats", "ce que j'ai vu et mesuré : un tableau, un graphique", "passé composé (ou présent), chiffres + unités"], ["5. Interprétation", "j'explique les résultats : pourquoi ?", "cause / conséquence"], ["6. Conclusion", "réponse à la question ; hypothèse confirmée ou infirmée ; loi générale", "présent de vérité générale"]], ["44mm", "84mm", "54mm"]) +
                '<div class="astuce" style="margin:2mm 0 0">✍️ Dans un rapport, on écrit de façon <b>objective</b> : <b>on</b> ou <b>nous</b> (« On a chauffé… », « Nous avons observé… »), pas d\'avis (« c\'était trop bien »), des <b>mesures précises</b> avec leur <b>unité</b> (25 °C, 3 min, 12 g).</div>')
    e = E("Dans quelle partie du rapport ? J'écris le numéro (1 à 6).", '<div class="card" style="line-height:1.9">___ Le sucre a disparu après 1 minute dans l\'eau chaude et après 6 minutes dans l\'eau froide.<br>___ Le sucre se dissout plus vite dans l\'eau chaude : l\'hypothèse est confirmée.<br>___ Je pense que le sucre se dissout plus vite dans l\'eau chaude.<br>___ Dans l\'eau chaude, les particules d\'eau bougent plus vite, donc elles « cassent » le sucre plus rapidement.<br>___ Verser 200 ml d\'eau dans chaque verre.</div>', ["lis", "numerote"], 1, "B",
          sol="4 · 6 · 2 · 5 · 3")
    b.page(f'{l5}{e}', "Leçon 5")
    pts = [(0, 20), (2, 42), (4, 63), (6, 84), (8, 100), (10, 100), (12, 100)]
    e = E("Je lis le graphique de l'expérience « chauffer de l'eau » et je réponds.", '<div class="grid2" style="align-items:center"><div>' + courbe(pts, "temps (minutes)", "température (°C)", 88, title="Température de l'eau pendant le chauffage") + '</div>' +
          f'<div><p class="sm">1. Quelle est la température au début ? {blank("m")}</p><p class="sm">2. Combien de degrés gagne-t-on en 2 minutes au début ? {blank("m")}</p><p class="sm">3. À partir de quelle minute la température ne change plus ? {blank("m")}</p><p class="sm">4. Que se passe-t-il à 100 °C ? {blank("l")}</p></div></div>', ["lis", "ecris"], 2, "B",
          sol="1. 20 °C — 2. environ 21 à 22 °C (de 20 à 42 °C) — 3. À partir de 8 minutes — 4. L'eau bout : elle passe de l'état liquide à l'état gazeux ; la température reste stable (palier) pendant l'ébullition.")
    e2 = E("Objectif ou pas ? Je réécris les phrases du rapport de Mateo de façon objective et précise.", '<div class="card" style="font-family:monospace;background:#fff;line-height:1.9">1. L\'eau était super chaude.<br>2. Le sucre a fondu hyper vite, c\'était trop cool.<br>3. J\'ai attendu un peu.</div>' + lines(3), ["lis", "ecris"], 2, "C",
           sol="Ex. : 1. L'eau était à 80 °C. 2. Le sucre s'est dissous en 1 minute (attention : il se dissout, il ne fond pas). 3. Nous avons attendu 5 minutes.")
    e3 = E("J'écris l'interprétation et la conclusion de l'expérience des graines (BD p. 3), en 4 phrases (cause, conséquence, présent de vérité générale).", lines(4), ["ecris"], 3, "C",
           sol="Ex. : Les graines ont germé dans les deux boîtes. Elles n'ont donc pas besoin de lumière pour germer, car elles utilisent les réserves qu'elles contiennent. L'hypothèse de Yonas est infirmée. Conclusion : une graine germe grâce à l'eau, à l'air et à la chaleur ; la lumière est nécessaire ensuite pour la croissance de la plante.")
    b.page(f'{e}{e2}{e3}', "S'entraîner")

    # ---------- Documents de la vie ----------
    eti = f'''<div class="doc" style="transform:none;border:2px solid #1F2A44;background:#fff;padding:3mm 4mm;font-size:9.6pt;line-height:1.4">
<div class="flex" style="justify-content:space-between"><div><b style="font-size:14pt;color:#3A6EA5">BRILLOR</b> · Détartrant WC gel · 750 ml<br><span class="xs muted">(produit et marque fictifs)</span></div>
<div class="flex" style="gap:2mm"><div style="width:16mm;height:16mm;border:2.5px solid #D62828;transform:rotate(45deg);display:flex;align-items:center;justify-content:center;background:#fff"><span style="transform:rotate(-45deg);font-size:13pt">🧪</span></div><div style="width:16mm;height:16mm;border:2.5px solid #D62828;transform:rotate(45deg);display:flex;align-items:center;justify-content:center;background:#fff"><span style="transform:rotate(-45deg);font-size:13pt;font-weight:800">!</span></div></div></div>
<p style="margin:2mm 0 0"><b style="color:#D62828">DANGER</b> · Provoque de graves brûlures de la peau et de graves lésions des yeux. Contient de l'acide.</p>
<p style="margin:1mm 0 0"><b>Conseils :</b> Tenir hors de portée des enfants. Porter des gants de protection. EN CAS DE CONTACT AVEC LES YEUX : rincer avec précaution à l'eau pendant plusieurs minutes. EN CAS D'INGESTION : rincer la bouche, NE PAS faire vomir. Ne pas mélanger avec de l'eau de Javel : dégagement de gaz dangereux.</p>
<p style="margin:1mm 0 0">📞 <b>Centre Antipoisons : 070 245 245</b> (gratuit, 24 h/24) · Urgences : 112</p></div>'''
    pic = '<div class="grid4" style="gap:2mm;margin-top:2mm">' + "".join(f'<div class="card c" style="padding:1.5mm"><div style="width:11mm;height:11mm;border:2px solid #D62828;transform:rotate(45deg);margin:2mm auto;display:flex;align-items:center;justify-content:center"><span style="transform:rotate(-45deg);font-size:11pt">{a}</span></div><span class="xs">{t}</span></div>' for a, t in [("🔥", "inflammable"), ("🧪", "corrosif"), ("💀", "toxique"), ("!", "irritant, nocif"), ("🐟", "dangereux pour l'environnement"), ("💥", "explosif"), ("🧍", "dangereux pour la santé (à long terme)"), ("🫙", "gaz sous pression")]) + '</div>'
    e = E("Je lis l'étiquette d'un produit ménager. Je réponds.", eti + pic + f'<p class="mt2">1. Pourquoi ce produit est-il dangereux ? {blank("xl")}</p><p>2. Quels pictogrammes vois-tu sur l\'étiquette ? Que veulent-ils dire ? {blank("xl")}</p><p>3. Que faut-il faire si le produit touche les yeux ? {blank("xl")}</p><p>4. Pourquoi ne faut-il pas le mélanger avec de l\'eau de Javel ? {blank("xl")}</p><p>5. Ton petit frère a avalé un peu de produit : qui appelles-tu ? Que ne fais-tu pas ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Il contient de l'acide : il provoque de graves brûlures de la peau et des yeux. — 2. Corrosif (🧪) et irritant / nocif (!). — 3. Rincer avec précaution à l'eau pendant plusieurs minutes. — 4. Parce que le mélange dégage des gaz dangereux. — 5. Le Centre Antipoisons (070 245 245) ou le 112 ; ne pas le faire vomir (lui rincer la bouche).")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span><h2>Une étiquette de produit ménager</h2>{e}', "Document de la vie")
    reg = f'''<div class="doc" style="transform:none;border:1.5px solid #9aa1b1;background:#FFFEF8;padding:3mm 4mm;font-size:9.8pt;line-height:1.45"><b style="color:{MC};font-size:12pt">🥽 Règlement du laboratoire de sciences · Institut Les Tilleuls</b> <span class="xs muted">(école fictive)</span>
<ol style="margin:1.5mm 0 0;padding-left:5mm"><li>L'élève n'entre au laboratoire qu'en présence du professeur.</li><li>Le port de la blouse est obligatoire ; les lunettes de protection sont obligatoires lors des manipulations de produits et lors des chauffages.</li><li>Les cheveux longs sont attachés. Il est interdit de manger et de boire.</li><li>On ne goûte, on ne sent directement aucun produit. Pour sentir une odeur, on rabat l'air vers soi avec la main.</li><li>Tout accident, même petit (coupure, brûlure, verre cassé), est signalé immédiatement au professeur.</li><li>À la fin de la séance, le matériel est nettoyé et rangé ; les déchets sont jetés dans les bacs prévus (jamais dans l'évier sans autorisation).</li></ol></div>'''
    e = E("Je lis le règlement du labo. Je réponds.", reg + f'<p class="mt2">1. Quand les lunettes sont-elles obligatoires ? {blank("xl")}</p><p>2. Comment sentir l\'odeur d\'un produit ? {blank("xl")}</p><p>3. Bilal s\'est coupé un peu le doigt, mais il ne dit rien. A-t-il raison ? Pourquoi ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Lors des manipulations de produits et lors des chauffages. — 2. En rabattant l'air vers soi avec la main, sans mettre le nez au-dessus. — 3. Non : tout accident, même petit, doit être signalé immédiatement au professeur (règle 5).")
    e2 = E("Je relève dans le règlement 3 verbes au passif et j'écris qui fait l'action (si on peut le savoir).", lines(2), ["lis", "ecris"], 3, "B",
           sol="Ex. : les cheveux sont attachés (par l'élève) · tout accident est signalé (par l'élève) · le matériel est nettoyé et rangé (par les élèves) · les déchets sont jetés (par les élèves).")
    e3 = E("J'écris 3 règles pour la cuisine de l'école (un autre lieu dangereux), à l'infinitif.", lines(3), ["ecris"], 2, "C",
           sol="Ex. : Se laver les mains avant de cuisiner. Ne pas laisser les manches des casseroles dépasser. Utiliser des maniques pour sortir un plat du four.")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span>{e}{e2}{e3}', "Document de la vie")

    # ---------- Vers les épreuves ----------
    pts2 = [(0, 2), (2, 4), (4, 7), (6, 11), (8, 14), (10, 16), (12, 17)]
    e = E("Entraînement de type CE1D sciences : je lis le document, je réponds et je justifie avec les données.", doc("Des élèves ont mesuré la hauteur d'une plante de haricot tous les deux jours.") + '<div class="grid2" style="align-items:center"><div>' + courbe(pts2, "temps (jours)", "hauteur (cm)", 85, ymax=20, xmax=12, title="Croissance d'une plante de haricot") + '</div>' +
          f'<div><p class="sm">a) Quelle est la hauteur de la plante au jour 6 ? {blank("m")}</p><p class="sm">b) Entre quels jours la plante grandit-elle le plus vite ? <b>Justifie</b> par un calcul. {blank("l")}</p><p class="sm">c) Que remarques-tu à la fin ? Propose une <b>hypothèse</b> pour l\'expliquer. {blank("l")}</p></div></div>' + lines(3), ["lis", "ecris"], 3, "C",
          sol="a) 11 cm. — b) Entre les jours 4 et 6 : + 4 cm (de 7 à 11 cm), plus que les autres périodes (+ 2, + 3, + 3, + 2, + 1). — c) La croissance ralentit (+ 1 cm entre les jours 10 et 12). Hypothèse : le pot est trop petit, la plante manque d'eau, de lumière ou de nutriments, ou elle approche de sa taille adulte.")
    e2 = E("Suite de l'épreuve. d) Calcule la croissance moyenne par jour entre le jour 0 et le jour 12. e) Un élève dit : « La plante grandit de la même façon chaque jour. » A-t-il raison ? <b>Justifie</b> avec deux données du graphique.", lines(4), ["ecris"], 3, "C",
           sol="d) (17 − 2) : 12 = 1,25 cm par jour. — e) Non : entre les jours 4 et 6, elle grandit de 4 cm, mais entre les jours 10 et 12 seulement de 1 cm ; la croissance n'est pas régulière.")
    b.page(EPR.format(k="CE1D", t="Lire un graphique, justifier") + e + e2 + '<div class="astuce">💡 <b>Au CE1D</b>, « justifie » veut dire : utilise les <b>données</b> du document (chiffres, unités) pour prouver ta réponse. Lis toujours le <b>titre</b> du graphique et les <b>axes</b> (quoi ? quelle unité ?) avant de répondre.</div>', "Vers les épreuves")
    e = E("Entraînement DELF B1 · production écrite (environ 160 mots). Sujet : « Dans votre école, une semaine des sciences est organisée. Vous avez participé à une expérience. Vous écrivez un article pour le journal de l'école : vous racontez l'expérience, ce que vous avez appris, et vous donnez votre avis sur cette semaine. »", '<div class="card sm" style="background:#fff">Plan conseillé : un titre · ① ce qu\'on a fait (passé composé, imparfait) · ② le résultat et ce que j\'ai appris (présent de vérité générale, cause) · ③ mon avis justifié (je trouve que…, parce que…) · une phrase de conclusion.</div>' + lines(14), ["ecris"], 3, "C",
          sol="Article d'environ 160 mots : titre, récit au passé, explication avec connecteurs de cause, avis argumenté. Grille DELF : respect de la consigne, cohérence, lexique, morphosyntaxe.")
    b.page(EPR.format(k="DELF B1", t="Écrire un article") + e, "Vers les épreuves")

    # ---------- Sons ----------
    e = E("Les sons [y] et [u]. J'écoute et je répète.", '<div class="grid2"><div class="card c"><div class="huge">[y] tube</div><p>les lèvres en avant, la langue en avant 😗<br>le t<b>u</b>be · la b<b>u</b>lle · la m<b>u</b>sique · la n<b>u</b>trition · d<b>û</b> à · la mes<b>u</b>re</p></div><div class="card c"><div class="huge">[u] loupe</div><p>les lèvres en avant, la langue en arrière 😮<br>la l<b>ou</b>pe · la p<b>ou</b>dre · bo<b>u</b>illir · le c<b>ou</b>rant · la so<b>u</b>ris · tr<b>ou</b>ble</p></div></div>', ["ecoute", "repete"], 1, "A",
          script="Faire sentir la différence : on dit [i] puis on avance les lèvres sans bouger la langue → [y] ; pour [u], la langue recule. Paires : tu / tout ; dessus / dessous ; la rue / la roue ; pur / pour ; une bulle / une boule.", sol="Activité orale.")
    e2 = E("J'écoute : [y] ou [u] ? Je coche.", checks(8, ["[y] tube", "[u] loupe"]), ["ecoute", "coche"], 2, "A", script="1. dessus — 2. dessous — 3. la roue — 4. la rue — 5. pur — 6. pour — 7. la bulle — 8. la boule",
           sol="1. [y] — 2. [u] — 3. [u] — 4. [y] — 5. [y] — 6. [u] — 7. [y] — 8. [u]")
    e3 = E("J'écris u ou ou.", '<div class="card big" style="line-height:2">la l___pe · le t___be · b___illir · la p___dre · la nature · la mes___re · le c___rant électrique · la t___rbine · la m___sc___lature</div>', ["complete"], 1, "C", sol="loupe · tube · bouillir · poudre · (nature) · mesure · courant · turbine · musculature")
    e4 = E("Je lis vite et bien (virelangue).", '<div class="card big c" style="line-height:1.8">Sous la loupe, une bulle pure bout,<br>tout au fond du tube où la poudre roule.</div>', ["lis", "parle"], 2, "B", sol="Lecture à voix haute.")
    b.page(f'<h2>J\'écoute bien · [y] et [u]</h2>{e}{e2}{e3}{e4}', "Sons")
    e = E("Lire les unités et les symboles à voix haute. J'écoute et je répète.", table(["On écrit…", "On lit…"], [["25 °C", "vingt-cinq degrés Celsius"], ["− 5 °C", "moins cinq degrés"], ["250 ml", "deux cent cinquante millilitres"], ["12 g", "douze grammes"], ["1 g/cm³", "un gramme par centimètre cube"], ["90 km/h", "nonante kilomètres par heure (ou kilomètres-heure)"], ["H₂O", "H deux O (la formule de l'eau)"], ["CO₂", "C O deux (le dioxyde de carbone)"]], ["50mm", "132mm"]), ["ecoute", "repete"], 1, "A",
          script="Lire chaque ligne ; faire répéter. Insister : on lit l'unité en entier (degrés, grammes) ; « par » pour la barre / ; nonante (Belgique).", sol="Activité orale.")
    e2 = E("Dictée scientifique. J'écoute et j'écris avec les symboles.", '<p>1. ______________ 2. ______________ 3. ______________ 4. ______________ 5. ______________</p>', ["ecoute", "ecris"], 2, "A",
           script="1. L'eau bout à cent degrés Celsius. — 2. Il fait moins douze degrés. — 3. Verser trois cents millilitres d'eau. — 4. Peser cinquante grammes de sel. — 5. Les plantes absorbent du CO deux.",
           sol="1. 100 °C — 2. − 12 °C — 3. 300 ml — 4. 50 g — 5. CO₂")
    e3 = E("Présenter des résultats à l'oral. En duo, je présente le tableau à mon voisin en 4 phrases : « Au début… Après… On constate que… Donc… ».", table(["Temps", "0 min", "2 min", "4 min", "6 min"], [["Eau chaude (sucre restant)", "10 g", "4 g", "0 g", "0 g"], ["Eau froide (sucre restant)", "10 g", "8 g", "6 g", "4 g"]], ["62mm", "30mm", "30mm", "30mm", "30mm"]), ["parle", "duo"], 2, "A",
           sol="Ex. : Au début, il y a 10 g de sucre dans chaque verre. Après 4 minutes, tout le sucre est dissous dans l'eau chaude, mais il reste 6 g dans l'eau froide. On constate que le sucre se dissout plus vite dans l'eau chaude. Donc la température accélère la dissolution.")
    b.page(f'<h2>J\'écoute bien · dire les mesures et les résultats</h2>{e}{e2}{e3}', "Sons")

    # ---------- Révision spirale ----------
    e = E("🔁 V3 · Module 2 · Les phrases avec « si ».", '<p>Si on (chauffer) ______________ l\'eau à 100 °C, elle bout. Si la Terre (être) ______________ plus près du Soleil, il (faire) ______________ beaucoup plus chaud.</p>', ["complete"], 1, "C", sol="chauffe · était · ferait")
    e2 = E("🔁 V3 · Module 2 · Les mesures. Je convertis.", '<p>1,5 l = ______ ml · 2 500 g = ______ kg · 3 min = ______ s</p>', ["complete"], 1, "C", sol="1 500 ml · 2,5 kg · 180 s")
    e3 = E("🔁 V3 · Module 1 · Les verbes des consignes. Que fais-tu quand on te demande de « justifier » ? Et de « décrire » ?", lines(2), ["ecris"], 1, "C", sol="Justifier : prouver sa réponse avec des données ou des raisons. Décrire : dire ce qu'on voit, comment c'est, sans expliquer.")
    e4 = E("🔁 V2 · Module 12 · Le passif.", '<p>On chauffe l\'eau. → L\'eau ______________ . · Le professeur a préparé le matériel. → Le matériel ______________ par le professeur.</p>', ["ecris"], 2, "C", sol="est chauffée · a été préparé")
    e5 = E("🔁 V2 · Module 10 · Notre planète. Explique avec « parce que » pourquoi il faut trier les déchets.", lines(1), ["ecris"], 1, "C", sol="Ex. : Il faut trier les déchets parce que certains matériaux peuvent être recyclés et que cela réduit la pollution.")
    e6 = E("🔁 V2 · Module 9 · Les quantités. Je complète avec : un peu de · beaucoup de · trop de.", '<p>Il ne faut pas mettre ______ sel dans l\'eau des plantes. Les plantes ont besoin de ______ lumière. Ajoute ______ sucre, pas tout le paquet !</p>', ["complete"], 1, "C", sol="trop de · beaucoup de · un peu de")
    b.page(f'<h2>🔁 Je révise les modules précédents</h2>{e}{e2}{e3}{e4}{e5}{e6}', "Je révise")

    # ---------- Ateliers ----------
    obj = [("🍎", "une pomme"), ("🪨", "un caillou"), ("🔑", "une clé"), ("🧽", "une éponge"), ("🪵", "un bouchon de liège"), ("🥚", "un œuf"), ("📎", "un trombone"), ("🧊", "un glaçon")]
    e = E("Ça flotte ou ça coule ? (groupe de 4, avec une bassine d'eau). Pour chaque objet : 1. chacun dit son hypothèse (« Je pense que… parce que… ») ; 2. on teste ; 3. on note le résultat ; 4. on dit si l'hypothèse est confirmée ou infirmée.", table(["Objet", "Mon hypothèse", "Résultat", "Confirmée / infirmée"], [[f'{a} {t}', "", "", ""] for a, t in obj], ["40mm", "50mm", "40mm", "52mm"]).replace("<td></td>", '<td style="height:7mm"></td>'), ["parle", "groupe", "ecris"], 2, "A",
          sol="Résultats habituels (eau douce) : la pomme, l'éponge, le bouchon de liège et le glaçon flottent ; le caillou, la clé, l'œuf frais et le trombone coulent. (Un trombone posé très délicatement peut rester à la surface grâce à la tension superficielle !)")
    e2 = E("Je m'évalue.", chk3(["J'ai formulé une hypothèse avec « je pense que… parce que… ».", "J'ai utilisé « confirmée » ou « infirmée ».", "J'ai écouté les hypothèses des autres."]), ["coche"], 1, "A", sol="Auto-évaluation.")
    b.page(f'{atl_head("A", "Atelier · Ça flotte ou ça coule ?")}{e}{e2}', "Atelier")
    cyc = f'''<div class="card" style="{SERIF};background:#F7FBF9;font-size:10.3pt">{S} <b>Le grand voyage de l'eau</b> <span class="xs muted">(texte documentaire écrit pour la classe)</span>
<p style="margin:1mm 0 0">Sur la Terre, la quantité d'eau ne change presque pas : elle circule sans cesse entre les océans, l'air, le sol et les êtres vivants. C'est le <b>cycle de l'eau</b>. Sous l'effet de la chaleur du Soleil, l'eau des océans, des lacs et des rivières s'évapore. Les plantes rejettent aussi de la vapeur d'eau par leurs feuilles : c'est la <b>transpiration</b>.</p>
<p style="margin:1mm 0 0">La vapeur d'eau monte dans l'atmosphère. Comme l'air est plus froid en altitude, elle se condense en minuscules gouttelettes qui forment les nuages. Lorsque les gouttelettes se regroupent et deviennent trop lourdes, elles tombent sous forme de pluie, de neige ou de grêle : ce sont les <b>précipitations</b>.</p>
<p style="margin:1mm 0 0">Une partie de cette eau ruisselle jusqu'aux rivières, qui la ramènent vers la mer. Une autre partie s'infiltre dans le sol et forme les <b>nappes phréatiques</b>, où l'on puise l'eau potable. En Wallonie, une grande partie de l'eau du robinet vient de ces eaux souterraines. Ainsi, l'eau que nous buvons aujourd'hui a peut-être déjà été un nuage, un glacier… ou une goutte de pluie tombée sur l'Ardenne !</p></div>'''
    e = E("Je lis le texte documentaire. Je réponds.", cyc + f'<p class="mt2">1. Qu\'est-ce que le cycle de l\'eau ? {blank("xl")}</p><p>2. Relève deux expressions de la cause dans le 2e paragraphe. {blank("xl")}</p><p>3. Remets dans l\'ordre : condensation · précipitations · évaporation · infiltration. {blank("xl")}</p><p>4. D\'où vient une grande partie de l\'eau du robinet en Wallonie ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. La circulation permanente de l'eau entre les océans, l'air, le sol et les êtres vivants. — 2. « Comme l'air est plus froid en altitude » ; « Lorsque les gouttelettes… deviennent trop lourdes » (+ « sous l'effet de la chaleur » au 1er §). — 3. évaporation → condensation → précipitations → infiltration. — 4. Des eaux souterraines (nappes phréatiques).")
    e2 = E("Je dessine le schéma légendé du cycle de l'eau (au moins 5 légendes : évaporation, condensation, nuage, précipitations, infiltration…).", '<div class="card" style="min-height:52mm;background:#fff"></div>', ["dessine", "ecris"], 2, "C", sol="Schéma légendé correct : flèches, légendes horizontales, titre.")
    b.page(f'{atl_head("B", "Atelier · Le grand voyage de l\'eau")}{e}{e2}', "Atelier")
    e = E("J'écris le rapport complet de l'expérience « Ça flotte ou ça coule ? » (atelier A), avec les 6 parties : titre et question, hypothèse, matériel et protocole, observations (tableau), interprétation, conclusion.", '<div class="card sm" style="background:#fff">Aide pour l\'interprétation : un objet flotte s\'il est « moins lourd que l\'eau pour un même volume » (on dit : moins <b>dense</b> que l\'eau). La forme compte aussi : un bateau en métal flotte grâce à sa forme creuse.</div>' + lines(16), ["ecris"], 2, "C",
          sol="Rapport en 6 parties ; tableau des résultats ; interprétation avec la cause (densité, matière, forme) ; conclusion au présent de vérité générale.")
    b.page(f'{atl_head("C", "Atelier · Mon premier rapport d\'expérience")}{e}', "Atelier")
    cards = [("La baleine est un poisson.", "F"), ("L'air a une masse.", "V"), ("Les araignées sont des insectes.", "F"), ("Le Soleil est une étoile.", "V"), ("Le son va plus vite que la lumière.", "F"), ("Les plantes respirent.", "V"),
             ("Dans le vide, une plume et une pierre tombent à la même vitesse.", "V"), ("La glace est plus lourde que l'eau liquide (même volume).", "F"), ("Le cœur est un muscle.", "V"), ("Les chauves-souris sont des oiseaux.", "F"), ("L'eau pure gèle à 0 °C.", "V"), ("Un aimant attire tous les métaux.", "F")]
    grid = '<div class="grid4" style="gap:1.5mm">' + "".join(f'<div class="card c" style="min-height:30mm;padding:2mm;background:{TINT if i % 2 == 0 else "#fff"};display:flex;flex-direction:column;justify-content:center"><span class="sm">{t}</span><span class="xs muted" style="margin-top:1mm">V ☐ F ☐</span></div>' for i, (t, _) in enumerate(cards)) + '</div>'
    e = E("Le quiz « Mythe ou science ? » (2 équipes). On découpe les cartes. Une équipe lit une carte ; l'autre dit « vrai » ou « faux » et JUSTIFIE avec « parce que… ». Bonne réponse justifiée = 2 points ; bonne réponse sans justification = 1 point.", grid, ["joue", "groupe"], 2, "D",
          sol="F (mammifère) · V · F (arachnides) · V · F (la lumière est beaucoup plus rapide : on voit l'éclair avant le tonnerre) · V · V · F (la glace flotte, elle est moins dense) · V · F (mammifères) · V · F (le fer, le nickel, le cobalt… pas l'aluminium ni le cuivre)")
    e2 = E("J'invente 3 cartes « Mythe ou science ? » avec leur réponse justifiée.", lines(3), ["ecris"], 2, "C", sol="Affirmations vérifiables avec justification correcte.")
    b.page(f'{atl_head("D", "Atelier · Mythe ou science ?")}{e}{e2}', "Atelier")

    # ---------- ★ Coup de pouce ----------
    e = E("Je relie l'état et l'image.", relie(["solide", "liquide", "gaz"], ["♨️ la vapeur", "🧊 la glace", "💧 l'eau"]), ["relie"], 1, "B", alpha=True, sol="solide → 🧊 · liquide → 💧 · gaz → ♨️")
    e2 = E("Je complète avec : fond · gèle · bout.", '<div class="card" style="background:#F2F6FD"><p class="big" style="line-height:2.2;margin:0">À 0 °C, l\'eau ______________ .<br>À 100 °C, l\'eau ______________ .<br>Au soleil, la glace ______________ .</p></div>', ["complete"], 1, "C", alpha=True, sol="gèle · bout · fond")
    e3 = E("Je relie l'objet et son nom.", relie(["🌡️", "🔬", "⚖️", "🥽"], ["les lunettes", "la balance", "le thermomètre", "le microscope"]), ["relie"], 1, "B", alpha=True, sol="🌡️ → thermomètre · 🔬 → microscope · ⚖️ → balance · 🥽 → lunettes")
    e4 = E("Vivant ou non vivant ? J'entoure.", '<div class="card big" style="line-height:2.1">un arbre (vivant / non vivant) · une pierre (vivant / non vivant)<br>un chat (vivant / non vivant) · l\'eau (vivant / non vivant)</div>', ["entoure"], 1, "B", alpha=True, sol="vivant · non vivant · vivant · non vivant")
    b.page(CP.format(t="La matière · le labo · le vivant") + e + e2 + e3 + e4, "★ Coup de pouce")
    e = E("Je complète avec : parce que · donc.", '<div class="card" style="background:#F2F6FD"><p class="big" style="line-height:2.2;margin:0">La glace fond ______________ il fait chaud.<br>Il fait froid, ______________ l\'eau gèle.<br>La plante meurt ______________ elle n\'a pas d\'eau.</p></div>', ["complete"], 1, "C", alpha=True, sol="parce qu' · donc · parce qu'")
    e2 = E("J'entoure le verbe au présent.", '<div class="card big" style="line-height:2.1">L\'eau (bout / a bouilli) à 100 °C.<br>La Terre (tournait / tourne) autour du Soleil.<br>Les oiseaux (pondent / pondaient) des œufs.</div>', ["entoure"], 1, "B", alpha=True, sol="bout · tourne · pondent")
    e3 = E("Je complète mon hypothèse avec le modèle.", '<div class="card" style="background:#F2F6FD"><p class="big" style="line-height:2.2;margin:0">Question : la plante a-t-elle besoin d\'eau ?<br>Je pense que la plante ______________ besoin d\'eau.<br>Pour vérifier, j\'arrose une plante et ______________ l\'autre.</p></div>', ["ecris"], 1, "C", alpha=True, sol="a · pas")
    e4 = E("Je recopie la phrase.", '<div class="card" style="background:#F2F6FD"><p class="big" style="margin:0">L\'hypothèse est confirmée.</p><p class="line"></p></div>', ["recopie"], 1, "C", alpha=True, sol="Copie correcte.")
    b.page(CP.format(t="Cause · présent · hypothèse") + e + e2 + e3 + e4, "★ Coup de pouce")
    e = E("Je légende le schéma avec : la fleur · la tige · la feuille · les racines · le fruit.", '<div class="c">' + plante(False, 110) + '</div>', ["ecris"], 1, "C", alpha=True, sol="① la fleur · ② la feuille · ③ la tige · ④ les racines · ⑤ le fruit")
    e2 = E("Je remets les étapes dans l'ordre (1 à 3).", '<div class="card big" style="line-height:2">___ J\'observe les graines.<br>___ Je mets des graines sur du coton.<br>___ J\'arrose le coton.</div>', ["numerote"], 1, "B", alpha=True, sol="3 · 1 · 2")
    e3 = E("Je dis à la prof ce que j'ai observé : « J'ai vu que… ».", '', ["parle"], 1, "A", alpha=True, sol="Phrase orale au passé composé.")
    e4 = E("Je recopie la règle de sécurité et je dessine le pictogramme.", '<div class="card" style="background:#F2F6FD"><p class="big" style="margin:0">Au labo, je porte des lunettes de protection.</p><p class="line"></p></div><div class="card" style="min-height:22mm;background:#fff"></div>', ["recopie", "dessine"], 1, "C", alpha=True, sol="Copie correcte + dessin de lunettes.")
    b.page(CP.format(t="Schéma · protocole") + e + e2 + e3 + e4, "★ Coup de pouce")

    # ---------- Tâche finale ----------
    e = E("En groupe, nous choisissons une expérience simple (ou une idée de la liste) et nous remplissons la fiche de préparation.", '<div class="card sm" style="background:#fff">Idées : 🧂 Le sel fait-il fondre la glace plus vite ? · 🍞 Le pain moisit-il plus vite au chaud ou au frigo ? · 🌱 Les plantes poussent-elles mieux avec de l\'eau sucrée ? · 🧲 Quels objets de la classe sont attirés par un aimant ? · 🍋 Le jus de citron empêche-t-il la pomme de brunir ?</div>' +
          table(["", "Nos notes"], [["❓ Notre question", ""], ["💡 Notre hypothèse (je pense que… parce que…)", ""], ["🔧 Le facteur qu'on change (la variable) et le témoin", ""], ["🧰 Le matériel", ""], ["⚠️ Les règles de sécurité", ""], ["📅 Qui fait quoi ? Quand ?", ""]], ["72mm", "110mm"]).replace("<td></td>", '<td style="height:19mm"></td>'), ["ecris", "groupe"], 1, "C",
          sol="Fiche complète : question précise, hypothèse justifiée, une seule variable, témoin, matériel, sécurité.")
    b.page(tache_head("Rapport de laboratoire complet", "En groupe, nous réalisons une vraie expérience : nous posons une question, nous formulons une hypothèse, nous écrivons le protocole, nous observons et mesurons, puis chacun écrit le rapport complet (6 parties, avec un tableau ou un graphique et un schéma légendé). Nous présentons nos résultats à la classe en 3 minutes.") + e, "Tâche finale", levels=False)
    e = E("J'écris le protocole et je note les observations de notre expérience.", '<p class="sm"><b>Matériel</b> :</p>' + lines(2) + '<p class="sm"><b>Protocole</b> (étapes à l\'infinitif) :</p>' + lines(7) + '<p class="sm mt2"><b>Tableau des observations</b> :</p>' + table(["", "Jour / mesure 1", "Jour / mesure 2", "Jour / mesure 3", "Jour / mesure 4"], [["Groupe testé", "", "", "", ""], ["Témoin", "", "", "", ""]], ["38mm", "36mm", "36mm", "36mm", "36mm"]).replace("<td></td>", '<td style="height:14mm"></td>') + '<p class="sm mt2"><b>Mon graphique</b> (titre, axes, unités) :</p><div class="card" style="min-height:55mm;background:#fff"></div>', ["ecris"], 2, "C",
          sol="Protocole précis et reproductible ; observations chiffrées avec unités.")
    b.page(e, "Tâche finale", levels=False)
    e = E("J'écris l'interprétation et la conclusion, et je dessine le schéma légendé de notre montage.", '<div class="grid2"><div>' + lines(14) + '</div><div class="card" style="min-height:100mm;background:#fff"><span class="xs muted">schéma légendé (titre !)</span></div></div>', ["ecris", "dessine"], 2, "C",
          sol="Interprétation avec cause / conséquence ; conclusion au présent ; hypothèse confirmée ou infirmée ; schéma conforme aux règles.")
    b.page(e + table(["Je vérifie mon rapport :", "✅"], [[x, '<span class="chk"></span>'] for x in ["Les 6 parties sont là, dans l'ordre.", "On ne change qu'une seule chose ; il y a un témoin.", "Les mesures ont une unité ; il y a un tableau ou un graphique.", "J'ai utilisé au moins 3 expressions de la cause ou de la conséquence.", "La conclusion est au présent et dit si l'hypothèse est confirmée ou infirmée.", "Mon schéma a un titre, des traits à la latte et des légendes horizontales."]], ["160mm", "22mm"]), "Tâche finale", levels=False)
    e = E("Je révise.", '<p>1. Le passage de l\'état solide à l\'état liquide : la ______________ 2. L\'eau bout à ______ °C. 3. « Une idée à vérifier » : une ______________ 4. Si l\'hypothèse est fausse, elle est ______________ . 5. La recette de l\'expérience : le ______________ 6. Le groupe où on ne change rien : le ______________ 7. Une cause positive : ______________ ; négative : ______________ 8. La conclusion est au présent de ______________ ______________ .</p>', ["ecris"], 2, "C",
          sol="1. fusion — 2. 100 — 3. hypothèse — 4. infirmée — 5. protocole — 6. témoin — 7. grâce à · à cause de — 8. vérité générale")
    e2 = E("Défi ! J'explique en 4 phrases pourquoi on met du sel sur les routes en hiver (cause, conséquence, présent de vérité générale).", lines(4), ["ecris"], 3, "C",
           sol="Ex. : En hiver, l'eau gèle sur les routes quand la température descend sous 0 °C. Le sel se dissout dans l'eau et abaisse la température à laquelle elle gèle. Grâce au sel, la glace fond même s'il fait un peu moins de 0 °C. C'est pourquoi les routes sont moins glissantes.")
    e3 = E("J'écris une hypothèse et la phrase « Si… alors… » pour la question : « Les plantes poussent-elles mieux avec de la musique ? »", lines(2), ["ecris"], 2, "C", sol="Ex. : Je pense que la musique n'a pas d'effet sur la croissance. Si mon hypothèse est juste, alors les plantes avec et sans musique auront la même taille après trois semaines.")
    e4 = E("Je corrige le rapport de Mateo : 4 erreurs (langue ou démarche).", '<div class="card" style="font-family:monospace;background:#fff;line-height:1.8">Hypothèse : le sucre fond plus vite dans l\'eau chaude.<br>Protocole : on a mis de l\'eau chaude et beaucoup de sucre dans un verre, et de l\'eau froide et un peu de sucre dans l\'autre.<br>Résultat : c\'était super rapide dans l\'eau chaude.<br>Conclusion : le sucre se dissolvait plus vite dans l\'eau chaude.</div>' + lines(3), ["lis", "ecris"], 3, "C",
           sol="1. « fond » → se dissout (dissolution, pas fusion). 2. Deux variables changent (température ET quantité de sucre) : il faut la même quantité de sucre. 3. Résultat pas objectif : donner des mesures (1 min / 6 min). 4. Conclusion au présent de vérité générale : « se dissout ».")
    b.page(f'<h2>🔁 Je révise tout le module</h2>{e}{e2}{e3}{e4}', "Je révise")

    # ---------- Test ----------
    Q = [("Le passage de l'état liquide à l'état solide s'appelle…", ["la solidification", "la fusion", "l'évaporation", "la condensation"]), ("La buée sur un miroir est un exemple de…", ["condensation", "fusion", "solidification", "dissolution"]), ("À la pression normale, l'eau pure bout à…", ["100 °C", "0 °C", "50 °C", "37 °C"]),
         ("Pour mesurer une masse, on utilise…", ["une balance", "un thermomètre", "une loupe", "un chronomètre"]), ("La baleine est…", ["un mammifère", "un poisson", "un reptile", "un amphibien"]), ("Un mélange d'eau et de sable est…", ["hétérogène", "homogène", "un gaz", "une dissolution"]),
         ("« L'eau bout à 100 °C » : c'est un présent…", ["de vérité générale", "d'actualité", "de narration", "du passé"]), ("Le sel ____ dans l'eau.", ["se dissout", "se dissoud", "se dissolve", "se dissous"]), ("Les liquides ____ à des températures différentes.", ["bouillent", "bouillissent", "bouent", "bouillent-ils"]),
         ("Les plantes poussent ____ la lumière.", ["grâce à", "à cause de", "donc", "parce que"]), ("Il fait froid, ____ l'eau gèle.", ["donc", "parce que", "car", "grâce à"]), ("« La chaleur ____ la dilatation des métaux. »", ["provoque", "est due à", "vient de", "à cause de"]),
         ("« Je pense que le sucre se dissout plus vite dans l'eau chaude » est…", ["une hypothèse", "une conclusion", "un protocole", "un résultat"]), ("Une hypothèse fausse est…", ["infirmée", "confirmée", "légendée", "protocolée"]), ("Dans une expérience juste, on change…", ["un seul facteur", "tous les facteurs", "deux facteurs", "rien du tout"]),
         ("Le groupe où on ne change rien s'appelle…", ["le témoin", "la variable", "l'hypothèse", "le protocole"]), ("Les étapes d'un protocole sont souvent…", ["à l'infinitif", "au passé simple", "au conditionnel", "au subjonctif"]), ("Sur un schéma légendé, les légendes sont écrites…", ["à l'horizontale", "en diagonale", "à la verticale", "sans article"]),
         ("Le numéro du Centre Antipoisons en Belgique est…", ["070 245 245", "112", "101", "100"]), ("🔁 Si on ____ la glace, elle fond.", ["chauffe", "chauffera", "chaufferait", "chauffait"])]
    ans = [q[1][0] for q in Q]
